  const article = { article_id: a.article_id, permalink: a.permalink, publication: a.publication, language: a.language, headline: a.headline, text_content: a.text_content };
  let extraction_error = null, raw = [];
  const ch = (resp.choices || [])[0];
  if (!ch) extraction_error = 'no_choices';
  else if (ch.message && ch.message.refusal) extraction_error = 'refusal';
  else if (ch.finish_reason === 'length') extraction_error = 'truncated_output';
  let summary = null;
  if (!extraction_error) { try { const parsed = JSON.parse(ch.message.content); raw = parsed.claims || []; summary = parsed.event && parsed.event.one_line_summary ? String(parsed.event.one_line_summary).slice(0, 300) : null; } catch (e) { extraction_error = 'invalid_json'; } }
  const claims = extraction_error ? [] : validateClaims(article, raw, req.story_id);
  const u = resp.usage || {};
  const inTok = u.prompt_tokens || 0, cTok = (u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0, outTok = u.completion_tokens || 0;
  const pr = PRICE[req.model];
  return { json: {
    article_id: a.article_id, story_id: req.story_id, content_hash: a.content_hash, prompt_version: PROMPT_VERSION, model: resp.model || req.model,
    extraction_error, summary, claims_json: JSON.stringify(claims),
    verified_count: claims.filter(c => c.status === 'verified').length, rejected_count: claims.filter(c => c.status === 'rejected').length,
    input_tokens: inTok, cached_input_tokens: cTok, output_tokens: outTok,
    est_cost_usd: pr ? Number((((inTok - cTok) * pr.input_per_1m + cTok * pr.cached_input_per_1m + outTok * pr.output_per_1m) / 1e6).toFixed(6)) : null,
    created_at: new Date().toISOString(),
  } };
});
return rows;

// ============================================================================
// WORKFLOW B — NODE: "Material check"   (Code node, Run Once for All Items)
// The planner chose stories before any facts existed. Now the facts are extracted
// and checked, so this step makes the plan fit the MATERIAL (no LLM):
//   - a story can only fill ~WORDS_PER_CLAIM words per verified fact (no padding)
//   - a full story with too few facts becomes a quick hit; a story with none is replaced by a reserve
//   - spare time goes to stories that have more material, then to reserve stories
// Every change is logged and shown on the page.
// Output: { stories: [{ story_id, role, angle, words, outlets, claims }], target_words, changes }.
// ============================================================================
const CFG = { WORDS_PER_CLAIM: 20, FRAMING_WORDS: 30, MIN_CLAIMS_FULL: 3, QUICK_HIT_WORDS: 35, MAX_CLAIMS_PER_STORY: 40, FIXED_WORDS: 40 };
// ~20 spoken words per verified fact; full stories also get ~30 words of framing (why it matters for you, background, transitions)
const S = $('Select stories').first().json;
const P = S.profile;
const newRows = $('Validate claims (batch)').all().map(i => i.json).filter(r => r.article_id);
const cacheRows = $('Get claim cache').all().map(i => i.json).filter(r => r.article_id && r.prompt_version === S.prompt_version);
const rowFor = id => newRows.find(r => r.article_id === id) || cacheRows.find(r => r.article_id === id);

function verifiedClaims(s) {
  const out = [], seen = new Set();
  for (const aid of s.source_article_ids || [s.representative_article_id]) {
    const row = rowFor(aid);
    for (const c of row ? JSON.parse(row.claims_json || '[]') : []) {
      if (c.status !== 'verified') continue;
      const key = c.statement.toLowerCase().replace(/\W+/g, ' ').trim();
      if (seen.has(key)) continue;
      seen.add(key); out.push(c);
    }
  }
  return out.slice(0, CFG.MAX_CLAIMS_PER_STORY);
}
const changes = [];
const target = S.plan.budget.target_words - CFG.FIXED_WORDS;
const reserves = (S.plan.reserves || []).map(s => ({ ...s, claims: verifiedClaims(s) })).filter(s => s.claims.length).sort((a, b) => b.claims.length - a.claims.length);
const capacity = st => (st.role === 'quick_hit' ? Math.min(45, st.claims.length * CFG.WORDS_PER_CLAIM) : st.claims.length * CFG.WORDS_PER_CLAIM + CFG.FRAMING_WORDS);

let plan = [];
for (const s of S.plan.selected) {
  const claims = verifiedClaims(s);
  let st = { ...s, claims, words: s.target_words };
  if (!claims.length) {
    const r = reserves.shift();
    if (r) { changes.push(`"${s.title}" had no verified facts - replaced by reserve "${r.title}"`); st = { ...r, role: s.role === 'quick_hit' || r.claims.length < CFG.MIN_CLAIMS_FULL ? 'quick_hit' : s.role, words: s.target_words, why: [...(r.why || []), `replaces "${s.title}"`] }; }
    else { changes.push(`"${s.title}" had no verified facts - dropped (no reserve left)`); continue; }
  } else if (st.role !== 'quick_hit' && claims.length < CFG.MIN_CLAIMS_FULL) {
    changes.push(`"${s.title}" has only ${claims.length} verified fact(s) - told as a quick hit`);
    st.role = 'quick_hit';
  }
  plan.push(st);
}
// words follow material
for (const st of plan) {
  const cap = capacity(st);
  const want = st.role === 'quick_hit' ? Math.min(st.words, CFG.QUICK_HIT_WORDS + 10) : st.words;
  if (cap < want) changes.push(`"${st.title}": ${want} words planned, material for about ${cap}`);
  st.words = Math.max(15, Math.min(want, cap));
}
let sum = () => plan.reduce((a, s) => a + s.words, 0);
// spare time -> stories with more material (planner's order = priority)
let deficit = target - sum();
for (const st of plan) {
  if (deficit <= 10) break;
  if (st.role === 'quick_hit') continue;
  const room = capacity(st) - st.words;
  if (room > 10) { const add = Math.min(room, deficit); st.words += add; deficit -= add; }
}
// still short -> reserves (as quick hits or full stories, depending on their material)
while (target - sum() > target * 0.12 && reserves.length) {
  const r = reserves.shift();
  const full = r.claims.length >= CFG.MIN_CLAIMS_FULL && target - sum() > 80;
  const st = { ...r, role: full ? 'second' : 'quick_hit', words: 0, why: [...(r.why || []), 'added to fill the length'] };
  st.words = Math.min(capacity(st), full ? target - sum() : CFG.QUICK_HIT_WORDS);
  plan.push(st);
  changes.push(`added reserve "${r.title}" (${st.role}) to fill the length`);
}
if (target - sum() > target * 0.12) changes.push(`only enough verified material for about ${Math.round((sum() + CFG.FIXED_WORDS) / 2.5)} seconds of the planned ${P.duration_seconds}`);
// the lead goes first
plan.sort((a, b) => (a.role === 'main' ? 0 : 1) - (b.role === 'main' ? 0 : 1));
if (plan.length && !plan.some(s => s.role === 'main')) { const best = plan.find(s => s.role === 'second'); if (best) best.role = 'main'; }

// give the writer exactly the facts that fit its word budget (it must use all of them): strongest facts, article order kept
const PRIO = { data_release: 1, company_result: 1, policy_decision: 1, upcoming_event: 2, context: 2, price_move: 3, forecast_or_estimate: 3, attributed_view: 4, other_fact: 5 };
for (const st of plan) {
  const n = Math.max(1, Math.round((st.words - (st.role === 'quick_hit' ? 0 : CFG.FRAMING_WORDS)) / CFG.WORDS_PER_CLAIM));
  if (st.claims.length <= n) continue;
  // explainer: facts without numbers first (story before figures); desk: figures first
  const figRank = c => (P.format === 'explainer' ? (c.figure ? 1 : 0) : P.format === 'desk' ? (c.figure ? 0 : 1) : 0);
  const keep = new Set(st.claims.map((c, i) => ({ c, i })).sort((a, b) => figRank(a.c) - figRank(b.c) || (PRIO[a.c.claim_type] || 9) - (PRIO[b.c.claim_type] || 9) || a.i - b.i).slice(0, n).map(x => x.c.claim_id));
  st.claims = st.claims.filter(c => keep.has(c.claim_id));
}
const stories = plan.map(s => ({
  story_id: s.story_id, title: s.title, role: s.role, angle: s.angle, words: Math.round(s.words), outlets: s.outlets, why: s.why,
  claims: s.claims.map(x => ({ claim_id: x.claim_id, statement: x.statement, type: x.claim_type, attribution: x.attribution, source: x.publication,
    figure: x.figure ? { value_text: x.figure.value_text, basis: x.figure.comparison_basis, measure: x.figure.measure, period: x.figure.period } : null })),
}));
return [{ json: { stories, target_words: S.plan.budget.target_words, planned_words: sum() + CFG.FIXED_WORDS, changes, unused_reserves: reserves.map(r => r.story_id) } }];

// ============================================================================
// WORKFLOW B — NODE: "Build writer request"   (Code node, Run Once for All Items)
// The WRITER turns the plan (after the material check) into a spoken script, using
// only the verified claims of each story. ONE REQUEST PER STORY (quick hits share one),
// each with its own word target - models hit 150-400 words reliably, not 1,500 at once.
// The lead request also writes the hook + teaser, the last one the closer (+ recap in long briefings).
// Greeting and sign-off are added by code. Output: one item per request { part, openai_body, ... }.
// ============================================================================
const WRITER = {
  USE_LLM_WRITER: true,          // false = template script (reads claims one by one)
  OPENAI_MODEL: 'gpt-6.1-terra',
  REASONING_EFFORT: 'medium',
};
const M = $('Material check').first().json;
const S = $('Select stories').first().json;
const P = S.profile;
const stories = M.stories;
const plan = { mode: S.planner.mode, interpretation: S.planner.interpretation, changes: M.changes };
const base = { plan, stories, target_words: M.target_words };
if (!WRITER.USE_LLM_WRITER || !stories.length) return [{ json: { use_writer: false, reason: stories.length ? 'writer disabled' : 'no story with verified facts', ...base } }];

const CH = P.character;
const KNOW = {
  beginner: `The listener is new to this: explain each unfamiliar term in one plain sentence the first time it appears, in ${CH.name}'s voice. Explanations are wanted, also for ${CH.name}.`,
  intermediate: CH.explain_default ? 'Explain a term only if most people would not know it.' : 'Do not define common terms.',
  expert: 'The listener knows the field: no definitions.',
}[P.expertise] || '';
const wordsTotal = stories.reduce((a, s) => a + s.words, 0);
const NAME = P.listener_name || null;
const HOOKS = (S.planner.listener_hooks || []).join('; ');
const BACKGROUND = (S.planner.background_needed || []).join('; ');
const KINDS = CH.segments;
const LANG = P.language || 'en';
const LANG_NAME = { en: 'English', de: 'German', nl: 'Dutch' }[LANG];
const LANGUAGE = LANG === 'en' ? '' : `LANGUAGE: write EVERY segment in ${LANG_NAME}, natural spoken ${LANG_NAME} as a native ${CH.name} would say it on ${LANG === 'de' ? 'German' : 'Dutch'} radio. The claims are in English: translate them faithfully, never adding or dropping meaning. ${LANG === 'de' ? 'Address the listener with "du".' : 'Address the listener with "je".'}
Numbers keep exactly the same values, written the ${LANG_NAME} way: decimal comma and the ${LANG_NAME} scale word (${LANG === 'de' ? '"3,5 Prozent", "115,8 Milliarden Dollar", "180.000"; never "Billion" for billion' : '"3,5 procent", "115,8 miljard dollar", "180.000"'}). Keep names of companies, people, indices and products as they are. Explanations of terms in ${LANG_NAME} too.`;
const SYSTEM = `You are ${CH.name}, the host of "${CH.show}", a personal morning news briefing. You talk to ONE listener${NAME ? ', ' + NAME : ''}: ${CH.listener}. You sound like ${CH.sounds_like}. Tone: ${CH.tone}.
Stay in character in EVERY sentence: a listener must be able to tell ${CH.name} from the other hosts after one sentence.

${CH.name.toUpperCase()}'S RULES
${CH.rules.map((r, i) => `${i + 1}. ${r}`).join('\n')}
Sentence pattern for each story: ${CH.pattern}.
Story order inside your part: ${CH.order}.
Numbers: ${CH.numbers}
When a fact leaves something open (no date, no timing, no duration), say it in ${CH.name}'s words: "${CH.uncertainty}" - never guess.
Words ${CH.name} uses naturally: ${CH.uses.map(w => '"' + w + '"').join(', ')}.
NEVER say: ${CH.never.map(w => '"' + w + '"').join(', ')}.
Avoid: ${CH.avoid}.
Signature move: ${CH.signature}
${KNOW}
${LANGUAGE}

THE SHARED RULE: you may simplify or leave out, but never add. No cause, forecast, amount or judgement that is not in the claims. Simplify wording only with the number kept ("a little, to 3.5 percent").

HOW IT SHOULD SOUND
- Connected, not a list of facts: each story follows the sentence pattern, and facts are linked to each other ("that is well above the 125 billion analysts expected"). Comparing two given numbers is allowed.
${KINDS.includes('for_you') ? `- One short "for_you" segment per main story links the facts already told to what this listener cares about (${HOOKS || 'their day'}), in ${CH.name}'s way. No new facts, no numbers, no predictions, never advice.` : `- ${CH.name} adds no personal commentary: no "for_you" segments.`}
- Move from story to story through content or with ${CH.name}'s own short transitions; never "Moving on" or "Now to stocks".
- Do NOT name outlets or say "X reports". The transcript links every source. Exceptions: opinions, forecasts and odds keep who said them ("analysts at Citi expect"). 
- Do NOT talk about sources, verification or evidence ("we cannot verify", "the material does not establish").
- Write for the ear: no lists, brackets, URLs, tickers or abbreviations a listener cannot hear.

FACT RULES - a sentence that breaks one is removed before it is spoken:
1. Every fact, number, name, date, cause and consequence comes from the CLAIMS of that story. Nothing from memory.
   If a story's reported_on date is more than a week before 2026-11-19, it is older background: say when it was reported ("back in September, ...") and never present it as today's news.
2. Every segment that states a fact lists the claim_ids it uses. Numbers exactly as in the claim ("percent" is fine), qualifiers kept ("more than", "around", the period, estimate vs actual).
3. Only state a cause if a claim attributes it. Views, forecasts and odds keep their attribution.
4. No investment advice, no greeting and no sign-off (both are added separately).
5. Use EVERY claim you are given at least once (skip only exact repeats). Reach the word target by telling more of the story in ${CH.name}'s pattern - never by inventing facts.

SEGMENT KINDS YOU MAY USE: ${KINDS.map(k => '"' + k + '"').join(', ')}.
"hook", "teaser", "story", "context" (fact segments, 1-3 sentences, with claim_ids) · "recap" (long briefings only: the 2-3 things to take away, built from facts already told, with their claim_ids) · "quick_hit" (one or two sentences)${KINDS.includes('for_you') ? ' · "for_you" (relevance, no facts, no numbers, no claim_ids)' : ''}${KINDS.includes('background') ? ` · "background" (${BACKGROUND ? 'explain: ' + BACKGROUND + ' - ' : ''}a general, timeless explanation in 1-2 plain sentences: no news, no numbers, no dates, no claim_ids; only if the listener is a beginner, asked for it, or it is listed here)` : ''} · "closer" (what happens next, from an upcoming_event claim with its claim_id, or the uncertainty line).
${S.planner.interpretation ? 'WHAT THEY WANT TODAY: ' + S.planner.interpretation : ''}
`;

const SCHEMA = {
  type: 'object', additionalProperties: false, required: ['segments'],
  properties: { segments: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['kind', 'text', 'claim_ids', 'story_id'],
    properties: { kind: { type: 'string', enum: KINDS }, text: { type: 'string' }, claim_ids: { type: 'array', items: { type: 'string' } }, story_id: { type: ['string', 'null'] } } } } },
};
let LASTSEEN = {}; try { LASTSEEN = Object.fromEntries($('Get stories').all().map(i => [i.json.story_id, String(i.json.last_seen || '').slice(0, 10)])); } catch (e) {}
const strip = st => ({ story_id: st.story_id, reported_on: LASTSEEN[st.story_id] || null, role: st.role, angle: st.angle, outlet_count: (st.outlets || []).length, claims: st.claims.map(c => ({ claim_id: c.claim_id, statement: c.statement, type: c.type, attribution: c.attribution, figure: c.figure })) });
// parts: every full story alone, all quick hits together (in plan order)
const full = stories.filter(st => st.role !== 'quick_hit');
const quick = stories.filter(st => st.role === 'quick_hit');
const parts = full.map(st => ({ stories: [st], words: st.words }));
if (quick.length) parts.push({ stories: quick, words: quick.reduce((a, q) => a + q.words, 0), quick: true });
const long = P.duration_seconds >= 300;
const items = parts.map((part, i) => {
  const first = i === 0, last = i === parts.length - 1;
  const others = parts.filter((_, k) => k !== i).flatMap(pp => pp.stories.map(st => st.angle));
  const duty = [
    first ? `This is the LEAD part. Start with a "hook" segment, then ${parts.length > 1 ? `one "teaser" sentence naming what else is coming (${others.slice(0, 4).join(' | ')}) - topics only, no facts, no numbers, then ` : ''}the story. ${CH.id === 'tide' ? 'The teaser may name the order (policy, reaction, data).' : ''}` : `This is part ${i + 1} of ${parts.length}. Start with this story's own most interesting fact - no announcement like "Now to..."; the previous part was about: ${parts[i - 1].stories.map(st => st.angle).join(' | ')}.`,
    first ? ((BACKGROUND || P.format === 'explainer') && KINDS.includes('background') ? `You are the only part allowed to write "background" segments: explain once, briefly, the concepts this listener needs for the WHOLE briefing${BACKGROUND ? ' (' + BACKGROUND + ')' : ''}, where they first matter.` : '') : (KINDS.includes('background') ? 'Do NOT write "background" segments - the lead part already explained the basics.' : ''),
    KINDS.includes('for_you') ? 'At most ONE "for_you" segment in your part.' : '',
    part.quick ? 'These are QUICK HITS: one "quick_hit" segment per story, one or two sentences each, in the given order. Link them naturally, without announcing.' : `Tell this ${part.stories[0].role === 'background' ? 'BACKGROUND story (how we got here - from earlier this week)' : 'story'} in ${CH.name}'s sentence pattern (${CH.pattern}) with "story"/"context"${KINDS.includes('for_you') ? '/"for_you"' : ''} segments.`,
    last ? (long ? 'This is the LAST part: after the story, add a "recap" segment (the 2-3 things to take away, citing claim_ids of facts from ANY part listed under recap_facts) and then a "closer" that looks ahead and does not repeat a number already said.' : 'This is the LAST part: end with a "closer" that looks ahead or ties the stories together - do not repeat a number already said.') : 'Do not write a closer.',
  ].join(' ');
  const lo = Math.round(part.words * 0.9), hi = Math.round(part.words * 1.1);
  const recapFacts = last && long ? stories.flatMap(st => st.claims.slice(0, 4).map(c => ({ claim_id: c.claim_id, statement: c.statement }))) : undefined;
  const body = {
    model: WRITER.OPENAI_MODEL,
    messages: [{ role: 'system', content: SYSTEM + `\nYOUR PART: ${duty}\nWORD TARGET FOR YOUR PART: between ${lo} and ${hi} words. Count them. Shorter is a failure unless you have used every claim.` },
      { role: 'user', content: JSON.stringify({ request_today: P.listener_question || null, stories: part.stories.map(strip), recap_facts: recapFacts }, null, 1) }],
    response_format: { type: 'json_schema', json_schema: { name: 'briefing_part', strict: true, schema: SCHEMA } },
    max_completion_tokens: 12000,
  };
  if (WRITER.REASONING_EFFORT) body.reasoning_effort = WRITER.REASONING_EFFORT;
  return { json: { use_writer: true, part: i, parts: parts.length, part_story_ids: part.stories.map(st => st.story_id), part_words: part.words, ...base, openai_body: body } };
});
return items;

// ============================================================================
// WORKFLOW B — NODE: "Check lengths"   (Code node, Run Once for All Items)
// Measures every written part against its word target. A part that came out more than
// 15% short gets ONE expansion request (same writer, its draft + facts it did not use yet).
// Output: one item per expansion request { expand: true, part, openai_body } - or a single { expand: false }.
// ============================================================================
const CFG = { MIN_SHARE: 0.85 };
const reqs = $('Build writer request').all().map(i => i.json);
const resps = $('OpenAI script writer').all().map(i => i.json);
const countWords = segs => segs.reduce((n, sg) => n + String(sg.text || '').split(/\s+/).filter(Boolean).length, 0);
const out = [];
reqs.forEach((req, k) => {
  if (!req.use_writer) return;
  const ch = ((resps[k] || {}).choices || [])[0];
  let segs = [];
  try { segs = JSON.parse(ch.message.content).segments || []; } catch (e) { segs = []; }
  const words = countWords(segs);
  if (!segs.length || words >= req.part_words * CFG.MIN_SHARE) return;
  const used = new Set(segs.flatMap(sg => sg.claim_ids || []));
  const partStories = req.stories.filter(st => req.part_story_ids.includes(st.story_id));
  const unused = partStories.flatMap(st => st.claims.filter(c => !used.has(c.claim_id)).map(c => ({ story_id: st.story_id, claim_id: c.claim_id, statement: c.statement, attribution: c.attribution })));
  const body = JSON.parse(JSON.stringify(req.openai_body));
  body.messages.push({ role: 'assistant', content: ch.message.content });
  body.messages.push({ role: 'user', content: `Your part has ${words} words; the target is ${req.part_words}. Rewrite the WHOLE part (same segment format, same duties) so it reaches between ${Math.round(req.part_words * 0.9)} and ${Math.round(req.part_words * 1.1)} words. Keep every fact you already used. Add these facts you have not used yet: ${JSON.stringify(unused)}. Tell more of the story: context, comparisons between the given facts, what it means for the listener, background concepts. Still no invented facts, no outlet names, no talk about sources.` });
  out.push({ json: { expand: true, part: req.part, words_before: words, target: req.part_words, openai_body: body } });
});
return out.length ? out : [{ json: { expand: false } }];

// ============================================================================
// WORKFLOW B — NODE: "Merge drafts"   (Code node, Run Once for All Items)
// Puts the written parts back together in plan order; an expanded version replaces the
// first draft when it is longer. Output: one item { merged, segments, usage, parts_report, writer_error }.
// ============================================================================
const reqs = $('Build writer request').all().map(i => i.json);
const resps = $('OpenAI script writer').all().map(i => i.json);
const checks = $('Check lengths').all().map(i => i.json);
const exp = $input.all().map(i => i.json);
const fromExpand = exp.some(e => e.choices);
const countWords = segs => segs.reduce((n, sg) => n + String(sg.text || '').split(/\s+/).filter(Boolean).length, 0);
const parse = r => { try { const ch = (r.choices || [])[0]; if (!ch || ch.finish_reason === 'length') return null; return JSON.parse(ch.message.content).segments || null; } catch (e) { return null; } };
const usageOf = (r, stage) => { const u = r.usage || {}; return { stage, model: r.model, input_tokens: u.prompt_tokens || 0, cached_input_tokens: (u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0, output_tokens: u.completion_tokens || 0 }; };
const usage = [], report = [], segments = [];
let failed = 0;
reqs.forEach((req, k) => {
  if (!req.use_writer) return;
  let segs = parse(resps[k] || {});
  if (resps[k] && resps[k].usage) usage.push(usageOf(resps[k], 'script_writer'));
  const words0 = segs ? countWords(segs) : 0;
  let expanded = false;
  if (fromExpand) {
    const ci = checks.findIndex(c => c.expand && c.part === req.part);
    if (ci >= 0 && exp[ci]) {
      if (exp[ci].usage) usage.push(usageOf(exp[ci], 'script_expand'));
      const e = parse(exp[ci]);
      if (e && countWords(e) > words0) { segs = e; expanded = true; }
    }
  }
  if (!segs) { failed++; return; }
  // each part has its duty: hook/teaser only in the lead part, recap/closer only in the last part
  const isFirst = req.part === 0, isLast = req.part === req.parts - 1;
  segs = segs.map(sg => (!isFirst && sg.kind === 'hook' ? { ...sg, kind: 'story' } : sg))
    .filter(sg => (isFirst || sg.kind !== 'teaser') && (isLast || !['recap', 'closer'].includes(sg.kind)));
  report.push({ part: req.part, stories: req.part_story_ids, target: req.part_words, words_first_draft: words0, words: countWords(segs), expanded });
  segments.push(...segs);
});
// the same sentence twice (e.g. a generic "for you" line in several parts) is said once
const seenText = new Set();
const words = t => new Set(String(t || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 3));
const similar = (a, b) => { const A = words(a), B = words(b); const inter = [...A].filter(w => B.has(w)).length; return inter / Math.max(1, Math.min(A.size, B.size)) >= 0.5; };
