let job = null;
try { job = $('Accept job').first().json.job_id; } catch (e) { return []; }
return [{ json: { job_id: job, status: 'running', created_at: new Date().toISOString(), input_json: null, result_json: JSON.stringify({ stage: "reading", progress: 0.3, label: "Reading the articles, pulling out facts" }), error: null } }];

let job = null;
try { job = $('Accept job').first().json.job_id; } catch (e) { return []; }
return [{ json: { job_id: job, status: 'running', created_at: new Date().toISOString(), input_json: null, result_json: JSON.stringify({ stage: "writing", progress: 0.5, label: "Writing the script" }), error: null } }];

let job = null;
try { job = $('Accept job').first().json.job_id; } catch (e) { return []; }
return [{ json: { job_id: job, status: 'running', created_at: new Date().toISOString(), input_json: null, result_json: JSON.stringify({ stage: "checking", progress: 0.72, label: "Fact-checking every sentence" }), error: null } }];

let job = null;
try { job = $('Accept job').first().json.job_id; } catch (e) { return []; }
return [{ json: { job_id: job, status: 'running', created_at: new Date().toISOString(), input_json: null, result_json: JSON.stringify({ stage: "recording", progress: 0.84, label: "Recording the audio" }), error: null } }];
